270	export function inferHeuristicDemographics(text: string): {
271	  gender: string;
272	  ageRange: string;
273	  location: string;
274	  confidence: number;
275	} {
276	  const normalized = String(text || '').toLowerCase();
277	
278	  let gender = 'UNKNOWN';
279	  if (B_SOU_MULHER_MINHA_ESPO_RE.test(normalized)) {
280	    gender = 'FEMININO';
281	  } else if (B_SOU_HOMEM_MEU_MARIDO_RE.test(normalized)) {
282	    gender = 'MASCULINO';
283	  }
284	
285	  const explicitAge = normalized.match(B__D_2___S_ANOS_B_RE);
286	  let ageRange = 'UNKNOWN';
287	  if (explicitAge) {
288	    const age = Number(explicitAge[1]);
289	    if (age >= 18 && age <= 24) {
290	      ageRange = '18-24';
291	    } else if (age <= 34) {
292	      ageRange = '25-34';
293	    } else if (age <= 44) {
294	      ageRange = '35-44';
295	    } else if (age <= 54) {
296	      ageRange = '45-54';
297	    } else if (age > 54) {
298	      ageRange = '55+';
299	    }
300	  }
301	
302	  const locationMatch = normalized.match(B___SOU_DE_MORO_EM_AQUI_RE) || null;
303	  const location = locationMatch?.[1] ? String(locationMatch[1]).trim() : 'UNKNOWN';
304	
305	  let confidence = 0;
306	  if (gender !== 'UNKNOWN') {
307	    confidence = Math.max(confidence, 0.35);
308	  }
309	  if (ageRange !== 'UNKNOWN') {
310	    confidence = Math.max(confidence, 0.55);
311	  }
312	  if (location !== 'UNKNOWN') {
313	    confidence = Math.max(confidence, 0.45);
314	  }
315	
316	  return {
317	    gender,
318	    ageRange,
319	    location,
320	    confidence,
321	  };
322	}

